  const before=Number((await f.database.query('SELECT count(*) AS n FROM tasks WHERE organization_id=$1',[f.organizationId])).rows[0].n),input={requestKey:randomUUID(),propertyId:f.propertyId,leadId:f.leadId,message:'Create a follow-up task.',task:{title:'Stage26 explicitly confirmed direct assistant task',dueAt:new Date(Date.now()+86400000).toISOString(),priority:'normal'}};
