 for(const route of ['/api/organization-admin/settings','/api/organization-admin/members','/api/organization-admin/options','/api/operations/health','/api/operations/audit','/api/operations/retention']){await deny(route,'','GET',undefined,401);await deny(route,agent,'GET',undefined,403);await deny(route,analyst,'GET',undefined,403);await deny(route,applicant,'GET',undefined,401);}
