 const updated=await json<OrganizationAdminSettings>('/api/organization-admin/settings',admin,'PUT',body),replayed=await json<OrganizationAdminSettings>('/api/organization-admin/settings',admin,'PUT',body);assert.equal(updated.version,replayed.version);assert.equal(updated.organization.name,body.name);assert.equal(updated.timeZone,'Europe/London');assert.equal((await json<{user:AuthUser}>('/api/auth/me',admin)).user.organization.name,body.name);assert.deepEqual((await json<{preferences:unknown}>('/api/account',admin)).preferences,accountBefore.preferences);
 await deny('/api/organization-admin/settings',admin,'PUT',{...body,requestKey:randomUUID()},409);await deny('/api/organization-admin/settings',admin,'PUT',{...profileBody(updated),organizationId:f.foreignOrganizationId},400);await deny('/api/organization-admin/settings',admin,'PUT',{...profileBody(updated),notifications:{inAppEnabled:true,emailEnabled:true,smsEnabled:false}},400);
