 const createKnowledge=(propertyId:string|null,title:string,body:string)=>json<{knowledge:OrganizationAdminKnowledge}>('/api/organization-admin/knowledge',admin,'POST',{requestKey:randomUUID(),propertyId,title,body,status:'approved',publicEnabled:true},201);
